 async function quickAdd(i,button){if(busy)return;if(read(sessionStorage,pendingKey,null)){$('#cart-button').click();return;}busy=true;button.disabled=true;try{const next=cart.map(l=>({...l})),line=next.find(l=>l.itemId===i.id&&!l.variantId&&!l.optionIds?.length&&!l.comment);if(line){if(line.quantity>=20)throw Error('Максимум 20 порций в строке.');line.quantity++;}else next.push({itemId:i.id,quantity:1,variantId:null,optionIds:[],comment:''});await api('stock-check',{items:next});cart=next;saveCart();$('#cafe-message').textContent='';}catch(e){$('#cafe-message').textContent=e.message;}finally{busy=false;button.disabled=false;}}
