 init();setInterval(async()=>{if(document.hidden)return;try{if($('#receipt-dialog').open&&receipt?.token)showReceipt(await request('/api/cafe/order?token='+receipt.token));}catch{}},10000);let refreshingMenu=false;async function refreshMenu(){if(refreshingMenu||!menu||document.hidden||document.querySelector('dialog[open]'))return;refreshingMenu=true;try{const next=await request('/api/cafe/menu');if(next.revision!==menu.revision||next.stockRevision!==menu.stockRevision){menu=next;renderMenu();}}catch{}finally{refreshingMenu=false;}}setInterval(refreshMenu,45000);document.addEventListener('visibilitychange',refreshMenu);window.addEventListener('focus',refreshMenu);
